<?php
if(!defined('ABSPATH'))exit;
$options=woogit_theme_options();$social=woogit_theme_items('social_links_json');$enamad=woogit_enamad_settings();$enamad_image=woogit_theme_image($options['enamad_image_id']??0,'medium');$show_enamad=$enamad['enabled']&&$enamad['placement']==='footer';$brand=$options['brand_name']??'WooGit';$footer_text=$options['footer_text']??($options['tagline']??'مدیریت هوشمند فروشگاه ووکامرس.');$copyright=$options['copyright_text']??'';
?><div class="wg-toast-region" aria-live="polite" aria-atomic="true"></div></main><footer class="wg-footer"><div class="wg-container wg-footer__grid"><div><strong><?php echo esc_html($brand);?></strong><p><?php echo woogit_safe_text($footer_text);?></p><?php if(!empty($options['phone'])):?><p><?php echo esc_html($options['phone']);?></p><?php endif;?><?php if(!empty($options['address'])):?><p><?php echo esc_html($options['address']);?></p><?php endif;?><?php if(!empty($options['support_hours'])):?><p><?php echo esc_html($options['support_hours']);?></p><?php endif;?><?php if($show_enamad):?><div class="wg-enamad" aria-label="نماد اعتماد الکترونیکی"><?php if($enamad['optional_text']):?><p><?php echo esc_html($enamad['optional_text']);?></p><?php endif;?><?php if($enamad_image):?><?php if($enamad['verification_url']):?><a href="<?php echo esc_url($enamad['verification_url']);?>" target="_blank" rel="noopener noreferrer"><img src="<?php echo esc_url($enamad_image);?>" alt="<?php echo esc_attr($enamad['alt_text']?:'نماد اعتماد الکترونیکی');?>" loading="lazy" width="120" height="120"></a><?php else:?><img src="<?php echo esc_url($enamad_image);?>" alt="<?php echo esc_attr($enamad['alt_text']?:'نماد اعتماد الکترونیکی');?>" loading="lazy" width="120" height="120"><?php endif;?><?php elseif($enamad['namad_code']):?><?php echo wp_kses_post($enamad['namad_code']);?><?php elseif($enamad['verification_url']):?><a class="wg-badge" href="<?php echo esc_url($enamad['verification_url']);?>" target="_blank" rel="noopener noreferrer">مشاهده نماد اعتماد</a><?php endif;?></div><?php endif;?></div><nav aria-label="ناوبری فوتر"><a href="<?php echo esc_url(woogit_page_url('privacy'));?>">حریم خصوصی</a><a href="<?php echo esc_url(woogit_page_url('terms'));?>">قوانین</a><a href="<?php echo esc_url(woogit_page_url('service-status'));?>">وضعیت سرویس</a><a href="<?php echo esc_url(woogit_page_url('support'));?>">پشتیبانی</a><a href="<?php echo esc_url(woogit_page_url('documentation'));?>">مستندات</a><?php if(!empty($options['support_email'])&&is_email($options['support_email'])):?><a href="<?php echo esc_url('mailto:'.$options['support_email']);?>"><?php echo esc_html($options['support_email']);?></a><?php endif;?><?php foreach($social as $item){if(!is_array($item)||empty($item['enabled']))continue;$url=esc_url($item['url']??'');$label=sanitize_text_field($item['label']??'');if($url&&$label)echo '<a href="'.esc_url($url).'" target="_blank" rel="noopener noreferrer">'.esc_html($label).'</a>';}?></nav></div><div class="wg-container wg-footer__bottom"><span><?php echo $copyright?esc_html($copyright):'© '.esc_html(wp_date('Y')).' '.esc_html($brand);?></span></div></footer><?php wp_footer();?></body></html>
